 1	import java.util.Arrays;
 2	import java.util.Comparator;
 3	import java.util.Objects;
 4	
 5	public class ActivitySelection {
 6	    private static final Comparator<Activity> BY_FINISH_TIME =
 7	        Comparator.comparingInt(Activity::finishTime);
 8	
 9	    private ActivitySelection() {
10	    }
11	
12	    public static int activitySelection(int[] start, int[] finish) {
13	        return countSelectedActivities(toSortedActivities(start, finish));
14	    }
15	
16	    private static Activity[] toSortedActivities(int[] start, int[] finish) {
17	        Objects.requireNonNull(start, "start must not be null");
18	        Objects.requireNonNull(finish, "finish must not be null");
19	
20	        if (start.length != finish.length) {
21	            throw new IllegalArgumentException("start and finish must have the same length");
22	        }
23	
24	        Activity[] activities = new Activity[start.length];
25	        for (int i = 0; i < start.length; i++) {
26	            activities[i] = new Activity(start[i], finish[i]);
27	        }
28	        Arrays.sort(activities, BY_FINISH_TIME);
29	        return activities;
30	    }
31	
32	    private static int countSelectedActivities(Activity[] activities) {
33	        if (activities.length == 0) {
34	            return 0;
35	        }
36	
37	        int count = 1;
38	        Activity lastSelected = activities[0];
39	
40	        // Greedily keep the earliest-finishing compatible activity.
41	        for (int i = 1; i < activities.length; i++) {
42	            Activity current = activities[i];
43	            if (current.canFollow(lastSelected)) {
44	                count++;
45	                lastSelected = current;
46	            }
47	        }
48	
49	        return count;
50	    }
51	
52	    public static void main(String[] args) {
53	        int[] start = {1, 3, 0, 5, 8, 5};
54	        int[] finish = {2, 4, 6, 7, 9, 9};
55	
56	        System.out.println(activitySelection(start, finish));
57	    }
58	
59	    private static final class Activity {
60	        private final int startTime;
61	        private final int finishTime;
62	
63	        private Activity(int startTime, int finishTime) {
64	            this.startTime = startTime;
65	            this.finishTime = finishTime;
66	        }
67	
68	        private int finishTime() {
69	            return finishTime;
70	        }
71	
72	        private boolean canFollow(Activity other) {
73	            return startTime > other.finishTime;
74	        }
75	
76	        @Override
77	        public String toString() {
78	            return "[" + startTime + ", " + finishTime + "]";
79	        }
80	    }
81	}

