51	    private static void assertEquals(int expected, int actual, String message) {
52	        if (expected != actual) {
53	            throw new AssertionError(message + ": expected " + expected + " but got " + actual);
54	        }
55	    }
56	
57	    private static void assertThrows(
58	        Class<? extends Throwable> expected,
59	        ThrowingRunnable runnable,
60	        String message
61	    ) {
62	        try {
63	            runnable.run();
64	        } catch (Throwable actual) {
65	            if (expected.isInstance(actual)) {
66	                return;
67	            }
68	            throw new AssertionError(
69	                message + ": expected " + expected.getSimpleName() + " but got " + actual.getClass().getSimpleName(),
70	                actual
71	            );
72	        }
73	
74	        throw new AssertionError(message + ": expected " + expected.getSimpleName() + " to be thrown");
75	    }
76	
77	    @FunctionalInterface
78	    private interface ThrowingRunnable {
79	        void run() throws Throwable;
80	    }
